   242          char cname[100];
   243          const char *name = igraph_gml_tree_name(gtree, i);
   244          if (!strcmp(name, "node")) {
   245              igraph_gml_tree_t *node;
   246              igraph_bool_t hasid;
   247              no_of_nodes++;
   248              if (igraph_gml_tree_type(gtree, i) != IGRAPH_I_GML_TREE_TREE) {
   249                  IGRAPH_ERROR("'node' is not a list", IGRAPH_PARSEERROR);
   250              }
   251              node = igraph_gml_tree_get_tree(gtree, i);
   252              hasid = 0;
   253              for (j = 0; j < igraph_gml_tree_length(node); j++) {
   254                  const char *name = igraph_gml_tree_name(node, j);
   255                  long int trieid, triesize = igraph_trie_size(&vattrnames);
   256                  IGRAPH_CHECK(igraph_trie_get(&vattrnames, name, &trieid));
   257                  if (trieid == triesize) {
   258                      /* new attribute */
   259                      igraph_attribute_record_t *atrec = igraph_Calloc(1, igraph_attribute_record_t);
   260                      int type = igraph_gml_tree_type(node, j);
   261                      if (!atrec) {
   262                          IGRAPH_ERROR("Cannot read GML file", IGRAPH_ENOMEM);
   263                      }
   264                      IGRAPH_CHECK(igraph_vector_ptr_push_back(&vattrs, atrec));
   265                      atrec->name = strdup(name);
   266                      if (type == IGRAPH_I_GML_TREE_INTEGER || type == IGRAPH_I_GML_TREE_REAL) {
   267                          atrec->type = IGRAPH_ATTRIBUTE_NUMERIC;
   268                      } else {
   269                          atrec->type = IGRAPH_ATTRIBUTE_STRING;
   270                      }
   271                  } else {
   272                      /* already seen, should we update type? */
   273                      igraph_attribute_record_t *atrec = VECTOR(vattrs)[trieid];
   274                      int type1 = atrec->type;
   275                      int type2 = igraph_gml_tree_type(node, j);
   276                      if (type1 == IGRAPH_ATTRIBUTE_NUMERIC && type2 == IGRAPH_I_GML_TREE_STRING) {
   277                          atrec->type = IGRAPH_ATTRIBUTE_STRING;
   278                      }
   279                  }
   280                  /* check id */
   281                  if (!hasid && !strcmp(name, "id")) {
   282                      long int id;
   283                      if (igraph_gml_tree_type(node, j) != IGRAPH_I_GML_TREE_INTEGER) {
   284                          IGRAPH_ERROR("Non-integer node id in GML file", IGRAPH_PARSEERROR);
   285                      }
   286                      id = igraph_gml_tree_get_integer(node, j);
   287                      snprintf(cname, sizeof(cname) / sizeof(char) -1, "%li", id);
   288                      IGRAPH_CHECK(igraph_trie_get(&trie, cname, &id));
   289                      hasid = 1;
   290                  }
   291              }
   292              if (!hasid) {
   293                  IGRAPH_ERROR("Node without 'id' while parsing GML file", IGRAPH_PARSEERROR);
   294              }
   295          } else if (!strcmp(name, "edge")) {
   296              igraph_gml_tree_t *edge;
   297              igraph_bool_t has_source = 0, has_target = 0;
   298              no_of_edges++;
   299              if (igraph_gml_tree_type(gtree, i) != IGRAPH_I_GML_TREE_TREE) {
   300                  IGRAPH_ERROR("'edge' is not a list", IGRAPH_PARSEERROR);
   301              }
   302              edge = igraph_gml_tree_get_tree(gtree, i);
   303              has_source = has_target = 0;
   304              for (j = 0; j < igraph_gml_tree_length(edge); j++) {
   305                  const char *name = igraph_gml_tree_name(edge, j);
   306                  if (!strcmp(name, "source")) {
   307                      has_source = 1;
   308                      if (igraph_gml_tree_type(edge, j) != IGRAPH_I_GML_TREE_INTEGER) {
   309                          IGRAPH_ERROR("Non-integer 'source' for an edge in GML file",
   310                                       IGRAPH_PARSEERROR);
   311                      }
   312                  } else if (!strcmp(name, "target")) {
   313                      has_target = 1;
   314                      if (igraph_gml_tree_type(edge, j) != IGRAPH_I_GML_TREE_INTEGER) {
   315                          IGRAPH_ERROR("Non-integer 'source' for an edge in GML file",
   316                                       IGRAPH_PARSEERROR);
   317                      }
   318                  } else {
   319                      long int trieid, triesize = igraph_trie_size(&eattrnames);
   320                      IGRAPH_CHECK(igraph_trie_get(&eattrnames, name, &trieid));
   321                      if (trieid == triesize) {
   322                          /* new attribute */
   323                          igraph_attribute_record_t *atrec = igraph_Calloc(1, igraph_attribute_record_t);
   324                          int type = igraph_gml_tree_type(edge, j);
   325                          if (!atrec) {
   326                              IGRAPH_ERROR("Cannot read GML file", IGRAPH_ENOMEM);
   327                          }
   328                          IGRAPH_CHECK(igraph_vector_ptr_push_back(&eattrs, atrec));
   329                          atrec->name = strdup(name);
   330                          if (type == IGRAPH_I_GML_TREE_INTEGER || type == IGRAPH_I_GML_TREE_REAL) {
   331                              atrec->type = IGRAPH_ATTRIBUTE_NUMERIC;
   332                          } else {
   333                              atrec->type = IGRAPH_ATTRIBUTE_STRING;
   334                          }
   335                      } else {
   336                          /* already seen, should we update type? */
   337                          igraph_attribute_record_t *atrec = VECTOR(eattrs)[trieid];
   338                          int type1 = atrec->type;
   339                          int type2 = igraph_gml_tree_type(edge, j);
   340                          if (type1 == IGRAPH_ATTRIBUTE_NUMERIC && type2 == IGRAPH_I_GML_TREE_STRING) {
   341                              atrec->type = IGRAPH_ATTRIBUTE_STRING;
   342                          }
   343                      }
   344                  }
   345              } /* for */
   346              if (!has_source) {
   347                  IGRAPH_ERROR("No 'source' for edge in GML file", IGRAPH_PARSEERROR);
   348              }
   349              if (!has_target) {
   350                  IGRAPH_ERROR("No 'target' for edge in GML file", IGRAPH_PARSEERROR);
   351              }
   352          } else {
   353              /* anything to do? Maybe add as graph attribute.... */
   354          }
   355      }
   356
   357      /* check vertex id uniqueness */
   358      if (igraph_trie_size(&trie) != no_of_nodes) {
   359          IGRAPH_ERROR("Node 'id' not unique", IGRAPH_PARSEERROR);
   360      }
   361
   362      /* now we allocate the vectors and strvectors for the attributes */
   363      for (i = 0; i < igraph_vector_ptr_size(&vattrs); i++) {
   364          igraph_attribute_record_t *atrec = VECTOR(vattrs)[i];
   365          int type = atrec->type;
   366          if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   367              igraph_vector_t *p = igraph_Calloc(1, igraph_vector_t);
   368              atrec->value = p;
   369              IGRAPH_CHECK(igraph_vector_init(p, no_of_nodes));
   370          } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   371              igraph_strvector_t *p = igraph_Calloc(1, igraph_strvector_t);
   372              atrec->value = p;
   373              IGRAPH_CHECK(igraph_strvector_init(p, no_of_nodes));
   374          } else {
   375              IGRAPH_WARNING("A composite attribute ignored");
   376          }
   377      }
   378
   379      for (i = 0; i < igraph_vector_ptr_size(&eattrs); i++) {
   380          igraph_attribute_record_t *atrec = VECTOR(eattrs)[i];
   381          int type = atrec->type;
   382          if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   383              igraph_vector_t *p = igraph_Calloc(1, igraph_vector_t);
   384              atrec->value = p;
   385              IGRAPH_CHECK(igraph_vector_init(p, no_of_edges));
   386          } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   387              igraph_strvector_t *p = igraph_Calloc(1, igraph_strvector_t);
   388              atrec->value = p;
   389              IGRAPH_CHECK(igraph_strvector_init(p, no_of_edges));
   390          } else {
   391              IGRAPH_WARNING("A composite attribute ignored");
   392          }
   393      }
   394
   395      /* Ok, now the edges, attributes too */
   396      IGRAPH_CHECK(igraph_vector_resize(&edges, no_of_edges * 2));
   397      p = -1;
   398      while ( (p = igraph_gml_tree_find(gtree, "edge", p + 1)) != -1) {
   399          igraph_gml_tree_t *edge;
   400          long int from, to, fromidx = 0, toidx = 0;
   401          char name[100];
   402          long int j;
   403          edge = igraph_gml_tree_get_tree(gtree, p);
   404          for (j = 0; j < igraph_gml_tree_length(edge); j++) {
   405              const char *n = igraph_gml_tree_name(edge, j);
   406              if (!strcmp(n, "source")) {
   407                  fromidx = igraph_gml_tree_find(edge, "source", 0);
   408              } else if (!strcmp(n, "target")) {
   409                  toidx = igraph_gml_tree_find(edge, "target", 0);
   410              } else {
   411                  long int edgeid = edgeptr / 2;
   412                  long int trieidx;
   413                  igraph_attribute_record_t *atrec;
   414                  int type;
   415                  igraph_trie_get(&eattrnames, n, &trieidx);
   416                  atrec = VECTOR(eattrs)[trieidx];
   417                  type = atrec->type;
   418                  if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   419                      igraph_vector_t *v = (igraph_vector_t *)atrec->value;
   420                      VECTOR(*v)[edgeid] = igraph_i_gml_toreal(edge, j);
   421                  } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   422                      igraph_strvector_t *v = (igraph_strvector_t *)atrec->value;
   423                      const char *value = igraph_i_gml_tostring(edge, j);
   424                      IGRAPH_CHECK(igraph_strvector_set(v, edgeid, value));
   425                  }
   426              }
   427          }
   428          from = igraph_gml_tree_get_integer(edge, fromidx);
   429          to = igraph_gml_tree_get_integer(edge, toidx);
   430          snprintf(name, sizeof(name) / sizeof(char) -1, "%li", from);
   431          IGRAPH_CHECK(igraph_trie_get(&trie, name, &from));
   432          snprintf(name, sizeof(name) / sizeof(char) -1, "%li", to);
   433          IGRAPH_CHECK(igraph_trie_get(&trie, name, &to));
   434          if (igraph_trie_size(&trie) != no_of_nodes) {
   435              IGRAPH_ERROR("Unknown node id found at an edge", IGRAPH_PARSEERROR);
   436          }
   437          VECTOR(edges)[edgeptr++] = from;
   438          VECTOR(edges)[edgeptr++] = to;
   439      }
   440
   441      /* and add vertex attributes */
   442      for (i = 0; i < igraph_gml_tree_length(gtree); i++) {
   443          const char *n;
   444          char name[100];
   445          long int j, k;
   446          n = igraph_gml_tree_name(gtree, i);
   447          if (!strcmp(n, "node")) {
   448              igraph_gml_tree_t *node = igraph_gml_tree_get_tree(gtree, i);
   449              long int iidx = igraph_gml_tree_find(node, "id", 0);
   450              long int id = igraph_gml_tree_get_integer(node, iidx);
   451              snprintf(name, sizeof(name) / sizeof(char) -1, "%li", id);
   452              igraph_trie_get(&trie, name, &id);
   453              for (j = 0; j < igraph_gml_tree_length(node); j++) {
   454                  const char *aname = igraph_gml_tree_name(node, j);
   455                  igraph_attribute_record_t *atrec;
   456                  int type;
   457                  igraph_trie_get(&vattrnames, aname, &k);
   458                  atrec = VECTOR(vattrs)[k];
   459                  type = atrec->type;
   460                  if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   461                      igraph_vector_t *v = (igraph_vector_t *)atrec->value;
   462                      VECTOR(*v)[id] = igraph_i_gml_toreal(node, j);
   463                  } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   464                      igraph_strvector_t *v = (igraph_strvector_t *)atrec->value;
   465                      const char *value = igraph_i_gml_tostring(node, j);
   466                      IGRAPH_CHECK(igraph_strvector_set(v, id, value));
   467                  }
   468              }
   469          }
   470      }
   471
   472      igraph_gml_tree_destroy(context.tree);
   473
   474      igraph_trie_destroy(&trie);
   475      igraph_trie_destroy(&gattrnames);
   476      igraph_trie_destroy(&vattrnames);
   477      igraph_trie_destroy(&eattrnames);
   478      IGRAPH_FINALLY_CLEAN(4);
   479
   480      IGRAPH_CHECK(igraph_empty_attrs(graph, 0, directed, 0)); /* TODO */
   481      IGRAPH_CHECK(igraph_add_vertices(graph, (igraph_integer_t) no_of_nodes,
   482                                       &vattrs));
   483      IGRAPH_CHECK(igraph_add_edges(graph, &edges, &eattrs));
   484
   485      igraph_i_gml_destroy_attrs(attrs);
   486      igraph_vector_destroy(&edges);
   487      igraph_gml_yylex_destroy(context.scanner);
   488      IGRAPH_FINALLY_CLEAN(3);
   489
   490      return 0;
   491  }
