   493  static int igraph_i_gml_convert_to_key(const char *orig, char **key) {
   494      int no = 1;
   495      char strno[50];
   496      size_t i, len = strlen(orig), newlen = 0, plen = 0;
   497
   498      /* do we need a prefix? */
   499      if (len == 0 || !isalpha(orig[0])) {
   500          no++;
   501          snprintf(strno, sizeof(strno) - 1, "igraph");
   502          plen = newlen = strlen(strno);
   503      }
   504      for (i = 0; i < len; i++) {
   505          if (isalnum(orig[i])) {
   506              newlen++;
   507          }
   508      }
   509      *key = igraph_Calloc(newlen + 1, char);
   510      if (! *key) {
   511          IGRAPH_ERROR("Writing GML file failed", IGRAPH_ENOMEM);
   512      }
   513      memcpy(*key, strno, plen * sizeof(char));
   514      for (i = 0; i < len; i++) {
   515          if (isalnum(orig[i])) {
   516              (*key)[plen++] = orig[i];
   517          }
   518      }
   519      (*key)[newlen] = '\0';
   520
   521      return 0;
   522  }
