    32  int igraph_gml_tree_init_integer(igraph_gml_tree_t *t,
    33                                   const char *name, int namelen,
    34                                   igraph_integer_t value) {
    35
    36      igraph_integer_t *p;
    37
    38      IGRAPH_UNUSED(namelen);
    39
    40      IGRAPH_VECTOR_PTR_INIT_FINALLY(&t->names, 1);
    41      IGRAPH_CHECK(igraph_vector_char_init(&t->types, 1));
    42      IGRAPH_FINALLY(igraph_vector_char_destroy, &t->types);
    43      IGRAPH_VECTOR_PTR_INIT_FINALLY(&t->children, 1);
    44
    45      /* names */
    46      VECTOR(t->names)[0] = (void*)name;
    47
    48      /* types */
    49      VECTOR(t->types)[0] = IGRAPH_I_GML_TREE_INTEGER;
    50
    51      /* children */
    52      p = igraph_Calloc(1, igraph_integer_t);
    53      if (!p) {
    54          IGRAPH_ERROR("Cannot create integer GML tree node", IGRAPH_ENOMEM);
    55      }
    56      *p = value;
    57      VECTOR(t->children)[0] = p;
    58
    59      IGRAPH_FINALLY_CLEAN(3);
    60      return 0;
    61  }
