   144  /* merge is destructive, the _second_ tree is destroyed */
   145  int igraph_gml_tree_mergedest(igraph_gml_tree_t *t1, igraph_gml_tree_t *t2) {
   146      long int i, n = igraph_vector_ptr_size(&t2->children);
   147      for (i = 0; i < n; i++) {
   148          IGRAPH_CHECK(igraph_vector_ptr_push_back(&t1->names, VECTOR(t2->names)[i]));
   149          IGRAPH_CHECK(igraph_vector_char_push_back(&t1->types, VECTOR(t2->types)[i]));
   150          IGRAPH_CHECK(igraph_vector_ptr_push_back(&t1->children,
   151                       VECTOR(t2->children)[i]));
   152      }
   153
   154      igraph_vector_ptr_destroy(&t2->names);
   155      igraph_vector_char_destroy(&t2->types);
   156      igraph_vector_ptr_destroy(&t2->children);
   157      return 0;
   158  }
