   160  void igraph_gml_tree_destroy(igraph_gml_tree_t *t) {
   161
   162      long int i, n = igraph_vector_ptr_size(&t->children);
   163      for (i = 0; i < n; i++) {
   164          int type = VECTOR(t->types)[i];
   165          switch (type) {
   166          case IGRAPH_I_GML_TREE_TREE:
   167              igraph_gml_tree_destroy(VECTOR(t->children)[i]);
   168              igraph_Free(VECTOR(t->names)[i]);
   169              break;
   170          case IGRAPH_I_GML_TREE_INTEGER:
   171              igraph_Free(VECTOR(t->children)[i]);
   172              igraph_Free(VECTOR(t->names)[i]);
   173              break;
   174          case IGRAPH_I_GML_TREE_REAL:
   175              igraph_Free(VECTOR(t->children)[i]);
   176              igraph_Free(VECTOR(t->names)[i]);
   177              break;
   178          case IGRAPH_I_GML_TREE_STRING:
   179              igraph_Free(VECTOR(t->children)[i]);
   180              igraph_Free(VECTOR(t->names)[i]);
   181              break;
   182          case IGRAPH_I_GML_TREE_DELETED:
   183              break;
   184          }
   185      }
